        return {"error": f"FEDEO 集合详情接口响应异常: {e}"}

    return {
        "source": "ESA FedEO STAC Catalogue (FedEO Clearinghouse / ESA EO-CAT)",
        "format": "json",
        "data": detail_data,
    }
