    if not arcgis_url:
        return {"error": "无法从 dataset_url / doi_landing_page 中解析出 ArcGIS REST 服务 URL"}

    arcgis_url = arcgis_url.split("?")[0].split("#")[0].rstrip("/")
    api_url = f"{arcgis_url}?f=json"

