    if not isinstance(payload, dict) or payload.get("success") is not True:
        return {'error': 'CKAN package_show 返回 success=false 或非预期结构: ' + str(payload), 'api_url': api_url}

    return {
        'source': 'British Columbia Data Catalogue (CKAN)', 
        'format': 'json', 
